describe('Product List Display - Inventory Page', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should display all 6 product cards with complete details after successful login', () => {
    // Login with standard user credentials
    cy.get('#user-name').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();

    // Verify navigation to inventory page
    cy.url().should('include', '/inventory.');

    // Verify all 6 product cards are displayed
    cy.get('[data-test="inventory-item"]').should('have.length', 6);

    // Verify each product card contains a name and price
    cy.get('[data-test="inventory-item"]').each(($item) => {
      cy.wrap($item).within(() => {
        // Verify product name exists and is not empty
        cy.get('[data-test="inventory-item-name"]').should('be.visible').should('have.length', 1).should('not.have.text', '');
        // Verify product price exists and starts with '$'
        cy.get('[data-test="inventory-item-price"]').should('be.visible').should('have.length', 1).should('have.text', '$');
      });
    });

    // Verify product names are visible and contain expected text
    cy.get('[data-test="inventory-item-name"]').should(($names) => {
      expect($names).to.all((name) => {
        const text = name.text();
        return text.length > 0 && text.includes('Sauce Labs');
      });
    });

    // Verify product prices are visible and contain expected format
    cy.get('[data-test="inventory-item-price"]').should(($prices) => {
      expect($prices).to.all((price) => {
        const text = price.text();
        return text.startsWith('$') && !isNaN(parseFloat(text.replace('$', '')));
      });
    });
  });

  it('should handle edge case when product list is empty or filtered', () => {
    // Login with standard user credentials
    cy.get('#user-name').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();

    // Verify inventory page loads
    cy.url().should('include', '/inventory.');

    // Filter by price (high to low)
    cy.get('[data-test="product-sort-container"]').select('hilo');

    // Verify product cards are still displayed after sorting
    cy.get('[data-test="inventory-item"]').should('have.length', 6);

    // Verify all product cards still contain name and price
    cy.get('[data-test="inventory-item"]').each(($item) => {
      cy.wrap($item).within(() => {
        cy.get('[data-test="inventory-item-name"]').should('be.visible').should('not.have.text', '');
        cy.get('[data-test="inventory-item-price"]').should('be.visible').should('have.text', '$');
      });
    });

    // Verify that the product list is not empty
    cy.get('[data-test="inventory-list"]').should('be.visible');
    cy.get('[data-test="inventory-list"]').should('contain', 'Sauce Labs');
  });
});
